function memoize(fn: (...args: number[]) => number): (...args: number[]) => number {
  const seen: [number[], number][] = [];
  return (...args: number[]) => {
    for (const [a, v] of seen) {
      if (a.length === args.length && a.every((x, i) => x === args[i])) return v;
    }
    const v = fn(...args);
    seen.push([args, v]);
    return v;
  };
}

function memoRun(fnName: string, calls: number[][]): number[][] {
  let count = 0;
  const base: Record<string, (...a: number[]) => number> = {
    add: (a, b) => { count++; return a + b; },
    fib: n => { count++; let x = 0, y = 1; for (let i = 0; i < n; i++) [x, y] = [y, x + y]; return x; },
    factorial: n => { count++; let f = 1; for (let i = 2; i <= n; i++) f *= i; return f; }
  };
  const wrapped = memoize(base[fnName]);
  return calls.map(args => [wrapped(...args), count]);
}

